use std::alloc::{GlobalAlloc, Layout};
use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
#[repr(align(64))]
struct Counter { requests: AtomicU64, bytes: AtomicU64 }
static COUNTERS: [Counter; 128] = [const { Counter { requests: AtomicU64::new(0), bytes: AtomicU64::new(0) } }; 128];
static NEXT: AtomicUsize = AtomicUsize::new(0);
std::thread_local! { static SLOT: std::cell::Cell<usize> = const { std::cell::Cell::new(usize::MAX) }; }
fn record(size: usize) {
    let slot = SLOT.try_with(|cell| {
        let index = cell.get();
        if index != usize::MAX { index } else {
            let index = NEXT.fetch_add(1, Ordering::Relaxed).min(127);
            cell.set(index);
            index
        }
    }).unwrap_or(127);
    COUNTERS[slot].requests.fetch_add(1, Ordering::Relaxed);
    COUNTERS[slot].bytes.fetch_add(size as u64, Ordering::Relaxed);
}
struct CountingAllocator;
#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        record(layout.size());
        mimalloc::MiMalloc.alloc(layout)
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        record(layout.size());
        mimalloc::MiMalloc.alloc_zeroed(layout)
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        record(size);
        mimalloc::MiMalloc.realloc(pointer, layout, size)
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) { mimalloc::MiMalloc.dealloc(pointer, layout) }
}
#[no_mangle]
pub extern "C" fn purust_alloc_counter(which: usize) -> u64 {
    COUNTERS.iter().map(|counter| if which == 0 { counter.requests.load(Ordering::Relaxed) } else { counter.bytes.load(Ordering::Relaxed) }).sum()
}

