// Keep the persistent PureScript Map representation. Typed native dictionaries
// preserve its ordering, including the Ord callback supplied for EvalRef/TcoRef.
fn purust_map_ord(compare: Func2<Value, Value, Purs_Data_Ordering::Ordering>) -> Rc<Purs_Data_Ord::Ord> {
    let equality = compare.clone();
    Rc::new(Purs_Data_Ord::Ord {
        compare,
        Eq0: Func1::Shared(Rc::new(move |_| {
            let equality = equality.clone();
            Rc::new(Purs_Data_Eq::Eq { eq: Func2::Shared(Rc::new(move |a, b| matches!(equality(a, b), Purs_Data_Ordering::Ordering::EQ))) })
        })),
    })
}

